/**
 * RionsTracker - Single File Fullstack (Vercel + Supabase)
 * Taruh file ini di: api/index.js  -> buka aplikasi di https://domain-kamu.vercel.app/api
 * Env wajib: SUPABASE_URL, SUPABASE_SERVICE_KEY, JWT_SECRET
 */
const crypto = require('crypto');
let SB_URL = (process.env.SUPABASE_URL || '').trim().replace(/\/rest\/v1\/?$/, '').replace(/\/+$/, '');
if (SB_URL && !/^https?:\/\//i.test(SB_URL)) SB_URL = 'https://' + SB_URL;
const SB_KEY = (process.env.SUPABASE_SERVICE_KEY || '').trim();
const SECRET = process.env.JWT_SECRET || 'ganti-secret-ini';
const HTML = "<!DOCTYPE html>\n<html lang=\"id\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no, viewport-fit=cover\">\n    <meta name=\"theme-color\" content=\"#f8fafc\">\n    <title>RionsTracker - Fullstack Edition</title>\n    <script src=\"https://cdn.tailwindcss.com\"></script>\n    <script src=\"https://unpkg.com/@phosphor-icons/web\"></script>\n    <script src=\"https://cdn.jsdelivr.net/npm/chart.js@4.4.2/dist/chart.umd.min.js\"></script>\n    <link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&display=swap\" rel=\"stylesheet\">\n    <script>\n        tailwind.config = {\n            theme: { extend: { fontFamily: { sans: ['Inter','sans-serif'] }, colors: { primary: '#4f46e5', 'primary-hover': '#4338ca' } } }\n        }\n    </script>\n    <style>\n        *{-webkit-tap-highlight-color:transparent}\n        ::-webkit-scrollbar{width:4px}::-webkit-scrollbar-track{background:transparent}::-webkit-scrollbar-thumb{background:rgba(203,213,225,.5);border-radius:10px}\n        body{background-color:#f8fafc;-webkit-font-smoothing:antialiased}\n        body::before,body::after{content:'';position:fixed;border-radius:50%;filter:blur(80px);z-index:-1;opacity:.35;pointer-events:none;transform:translateZ(0)}\n        body::before{width:40vw;height:40vw;min-width:250px;min-height:250px;background:#818cf8;top:-10%;right:-5%;animation:moveBlob 25s infinite alternate ease-in-out}\n        body::after{width:50vw;height:50vw;min-width:300px;min-height:300px;background:#2dd4bf;bottom:-10%;left:-10%;animation:moveBlob 25s infinite alternate-reverse ease-in-out -10s}\n        .bg-blob-3{position:fixed;width:45vw;height:45vw;min-width:300px;min-height:300px;background:#f472b6;border-radius:50%;filter:blur(80px);z-index:-1;opacity:.25;top:40%;left:40%;animation:moveBlob 30s infinite alternate ease-in-out -5s;pointer-events:none;transform:translateZ(0)}\n        @media(max-width:768px){.bg-blob-3{display:none}body::before,body::after{filter:blur(40px);opacity:.2}}\n        @keyframes moveBlob{0%{transform:translate(0,0) scale(1) rotate(0)}50%{transform:translate(3vw,3vh) scale(1.05) rotate(5deg)}100%{transform:translate(0,0) scale(1) rotate(0)}}\n        .liquid-glass{backdrop-filter:blur(20px) saturate(140%);-webkit-backdrop-filter:blur(20px) saturate(140%);transform:translateZ(0);transition:all .25s cubic-bezier(.4,0,.2,1);background:rgba(255,255,255,.45);border:1px solid rgba(255,255,255,.6);box-shadow:0 8px 32px 0 rgba(31,38,135,.05),inset 0 0 0 1px rgba(255,255,255,.4)}\n        .liquid-glass-dark{backdrop-filter:blur(20px) saturate(140%);-webkit-backdrop-filter:blur(20px) saturate(140%);transform:translateZ(0);transition:all .25s cubic-bezier(.4,0,.2,1);background:linear-gradient(135deg,rgba(79,70,229,.75),rgba(67,56,202,.85));border:1px solid rgba(255,255,255,.3);box-shadow:0 8px 32px 0 rgba(79,70,229,.25),inset 0 0 0 1px rgba(255,255,255,.2)}\n        .glass-shine{position:relative;overflow:hidden}.glass-shine::after{content:'';position:absolute;top:0;left:-150%;width:50%;height:100%;background:linear-gradient(to right,transparent,rgba(255,255,255,.4),transparent);transform:skewX(-25deg);pointer-events:none}.glass-shine:hover::after{animation:shine .8s forwards}@keyframes shine{100%{left:150%}}\n        .anim-float{animation:floating 6s ease-in-out infinite}@keyframes floating{0%,100%{transform:translateY(0)}50%{transform:translateY(-3px)}}\n        .btn-morph{border-radius:60% 40% 30% 70%/60% 30% 70% 40%;animation:morphing 8s ease-in-out infinite;transition:all .3s cubic-bezier(.4,0,.2,1)}.btn-morph:hover{border-radius:50%;transform:scale(1.05) translateY(-2px);box-shadow:0 12px 25px rgba(79,70,229,.5)}@keyframes morphing{0%,100%{border-radius:60% 40% 30% 70%/60% 30% 70% 40%}50%{border-radius:30% 60% 70% 40%/50% 60% 30% 60%}}\n        .pb-safe{padding-bottom:env(safe-area-inset-bottom,1.5rem)}.pt-safe{padding-top:env(safe-area-inset-top,1rem)}\n        .fade-in{animation:fadeIn .25s cubic-bezier(.16,1,.3,1)}@keyframes fadeIn{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:translateY(0)}}\n        .hidden-view{display:none!important}\n        @keyframes toastSlide{0%{transform:translateY(-100%) scale(.9);opacity:0}15%,85%{transform:translateY(0) scale(1);opacity:1}100%{transform:translateY(-100%) scale(.9);opacity:0}}.toast-animate{animation:toastSlide 3.5s forwards cubic-bezier(.16,1,.3,1)}\n        .pulse-badge{animation:pulse 2s cubic-bezier(.4,0,.6,1) infinite}@keyframes pulse{0%,100%{opacity:1}50%{opacity:.5}}\n        input,select{font-size:16px!important}\n        .spin{animation:spin 1s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}\n        .page-auth{display:flex!important}\n    </style>\n</head>\n<body class=\"text-slate-800 h-screen overflow-hidden flex selection:bg-indigo-500/20\">\n<div class=\"bg-blob-3\"></div>\n\n<!-- ═══════════════════════════════════════════════════════════════════\n     AUTH PAGE\n════════════════════════════════════════════════════════════════════ -->\n<div id=\"authPage\" class=\"hidden fixed inset-0 z-[90] items-center justify-center p-4\" style=\"background:rgba(248,250,252,0.95);backdrop-filter:blur(30px)\">\n    <div class=\"liquid-glass w-full max-w-sm rounded-3xl shadow-2xl p-8 fade-in\">\n        <!-- Logo -->\n        <div class=\"flex flex-col items-center mb-8\">\n            <div class=\"w-16 h-16 rounded-2xl bg-gradient-to-br from-indigo-500 to-purple-600 flex items-center justify-center text-white shadow-xl shadow-indigo-500/30 mb-4\">\n                <i class=\"ph-fill ph-wallet text-3xl\"></i>\n            </div>\n            <h1 class=\"text-2xl font-extrabold bg-clip-text text-transparent bg-gradient-to-r from-indigo-600 to-purple-600\">RionsTracker</h1>\n            <p class=\"text-slate-500 text-sm mt-1 font-medium\">Lacak keuangan dengan mudah</p>\n        </div>\n\n        <!-- Tab -->\n        <div class=\"bg-slate-200/50 p-1 rounded-2xl flex text-sm font-bold mb-6\">\n            <button id=\"tabLoginBtn\" onclick=\"setAuthTab('login')\" class=\"flex-1 py-2.5 rounded-xl bg-white text-slate-800 shadow-sm transition-all\">Masuk</button>\n            <button id=\"tabRegisterBtn\" onclick=\"setAuthTab('register')\" class=\"flex-1 py-2.5 rounded-xl text-slate-500 hover:text-slate-800 transition-all\">Daftar</button>\n        </div>\n\n        <form id=\"authForm\" onsubmit=\"handleAuthSubmit(event)\" class=\"space-y-4\">\n            <div>\n                <label class=\"block text-xs font-bold text-slate-600 mb-1.5\">Username</label>\n                <input type=\"text\" id=\"authUsername\" required autocomplete=\"username\" minlength=\"3\"\n                    class=\"w-full px-4 py-3 bg-white/70 border border-white/80 rounded-xl font-semibold outline-none focus:ring-2 focus:ring-indigo-500 shadow-sm transition-all\"\n                    placeholder=\"Contoh: fardan\">\n            </div>\n            <div>\n                <label class=\"block text-xs font-bold text-slate-600 mb-1.5\">Password</label>\n                <div class=\"relative\">\n                    <input type=\"password\" id=\"authPassword\" required autocomplete=\"current-password\" minlength=\"6\"\n                        class=\"w-full px-4 py-3 bg-white/70 border border-white/80 rounded-xl font-semibold outline-none focus:ring-2 focus:ring-indigo-500 shadow-sm transition-all\"\n                        placeholder=\"••••••••\">\n                    <button type=\"button\" onclick=\"togglePassVis()\" class=\"absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600 p-1\">\n                        <i id=\"passEyeIcon\" class=\"ph ph-eye text-lg\"></i>\n                    </button>\n                </div>\n            </div>\n            <p id=\"authError\" class=\"text-xs font-bold text-rose-600 hidden px-1\"></p>\n            <button type=\"submit\" id=\"authSubmitBtn\"\n                class=\"w-full py-3.5 bg-gradient-to-r from-indigo-500 to-purple-600 text-white font-bold rounded-xl shadow-lg shadow-indigo-500/30 active:scale-95 transition-all flex items-center justify-center gap-2\">\n                <i class=\"ph-bold ph-sign-in text-lg\"></i>\n                <span id=\"authSubmitLabel\">Masuk</span>\n            </button>\n        </form>\n\n        <p class=\"text-center text-xs text-slate-500 mt-5\">\n            <span id=\"authSwitchText\">Belum punya akun?</span>\n            <button onclick=\"setAuthTab('register')\" id=\"authSwitchBtn\" class=\"text-indigo-600 font-bold hover:underline ml-1\">Daftar</button>\n        </p>\n\n        \n    </div>\n</div>\n\n<!-- ═══════════════════════════════════════════════════════════════════\n     MAIN APP\n════════════════════════════════════════════════════════════════════ -->\n<aside id=\"sidebarEl\" class=\"hidden md:flex flex-col w-72 liquid-glass h-full border-r border-white/50 z-10 relative\">\n    <div class=\"p-6 flex items-center justify-between pt-safe\">\n        <div class=\"flex items-center gap-3\">\n            <div class=\"w-10 h-10 rounded-xl bg-gradient-to-br from-indigo-500 to-purple-500 flex items-center justify-center text-white shadow-lg shadow-indigo-500/30\">\n                <i class=\"ph-fill ph-wallet text-2xl\"></i>\n            </div>\n            <h1 class=\"text-xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-indigo-600 to-purple-600\">RionsTracker</h1>\n        </div>\n    </div>\n    <div class=\"px-6 py-2\">\n        <div class=\"bg-indigo-500/10 backdrop-blur-md border border-indigo-500/20 text-indigo-600 px-3 py-1.5 rounded-xl text-xs flex items-center gap-2 shadow-sm\">\n            <span class=\"w-2 h-2 rounded-full bg-indigo-500 pulse-badge\"></span>\n            <span id=\"sidebarStatus\" class=\"font-medium\">Terhubung ke Server</span>\n        </div>\n    </div>\n    <nav class=\"flex-1 px-4 space-y-2 mt-4\">\n        <button onclick=\"switchView('dashboard')\" id=\"nav-dashboard-desktop\" class=\"w-full flex items-center gap-3 px-4 py-3.5 rounded-2xl text-indigo-600 bg-white/60 font-semibold shadow-sm transition-all border border-white/80\">\n            <i class=\"ph-fill ph-squares-four text-xl\"></i> Dashboard\n        </button>\n        <button onclick=\"switchView('transactions')\" id=\"nav-transactions-desktop\" class=\"w-full flex items-center gap-3 px-4 py-3.5 rounded-2xl text-slate-500 hover:bg-white/40 hover:text-slate-900 font-medium transition-all\">\n            <i class=\"ph ph-list-dashes text-xl\"></i> Semua Transaksi\n        </button>\n        <button onclick=\"openBudgetModal()\" class=\"w-full flex items-center gap-3 px-4 py-3.5 rounded-2xl text-slate-500 hover:bg-white/40 hover:text-slate-900 font-medium transition-all\">\n            <i class=\"ph ph-target text-xl\"></i> Target Anggaran\n        </button>\n        <button onclick=\"openCategoryModal()\" class=\"w-full flex items-center gap-3 px-4 py-3.5 rounded-2xl text-slate-500 hover:bg-white/40 hover:text-slate-900 font-medium transition-all\">\n            <i class=\"ph ph-tag text-xl\"></i> Kelola Kategori\n        </button>\n        <button onclick=\"exportData()\" class=\"w-full flex items-center gap-3 px-4 py-3.5 rounded-2xl text-slate-500 hover:bg-white/40 hover:text-slate-900 font-medium transition-all\">\n            <i class=\"ph ph-download-simple text-xl\"></i> Export CSV\n        </button>\n    </nav>\n    <div class=\"p-6 border-t border-white/50 pb-safe\">\n        <div class=\"flex items-center justify-between bg-white/40 p-3 rounded-2xl border border-white/60\">\n            <div class=\"flex items-center gap-3 overflow-hidden\">\n                <div class=\"w-10 h-10 rounded-full bg-indigo-100 text-indigo-600 flex items-center justify-center font-bold shadow-inner shrink-0\">\n                    <i class=\"ph-fill ph-user-circle text-2xl\"></i>\n                </div>\n                <div class=\"overflow-hidden\">\n                    <p class=\"text-[10px] font-bold text-slate-400 uppercase tracking-wider\">Logged in as</p>\n                    <p class=\"text-xs font-mono font-semibold text-slate-700 truncate\" id=\"sidebarUsername\">—</p>\n                </div>\n            </div>\n            <button onclick=\"logout()\" class=\"w-8 h-8 flex items-center justify-center bg-white rounded-xl text-rose-500 shadow-sm hover:bg-rose-500 hover:text-white transition-colors shrink-0\" title=\"Logout\">\n                <i class=\"ph-bold ph-sign-out\"></i>\n            </button>\n        </div>\n    </div>\n</aside>\n\n<nav class=\"md:hidden fixed bottom-0 w-full liquid-glass border-t border-white/50 flex justify-around p-2 z-40 pb-safe shadow-[0_-10px_40px_rgba(0,0,0,0.05)]\">\n    <button onclick=\"switchView('dashboard')\" id=\"nav-dashboard-mobile\" class=\"flex flex-col items-center p-2 text-indigo-600 w-20 transition-transform active:scale-95\">\n        <i class=\"ph-fill ph-squares-four text-2xl mb-1\"></i><span class=\"text-[10px] font-bold\">Beranda</span>\n    </button>\n    <div class=\"relative -top-6\">\n        <button onclick=\"openModal()\" class=\"btn-morph w-14 h-14 bg-gradient-to-tr from-indigo-500 to-purple-500 text-white flex items-center justify-center shadow-[0_8px_20px_rgba(79,70,229,0.4)] border-[3px] border-white/80\">\n            <i class=\"ph ph-plus text-2xl font-bold\"></i>\n        </button>\n    </div>\n    <button onclick=\"switchView('transactions')\" id=\"nav-transactions-mobile\" class=\"flex flex-col items-center p-2 text-slate-400 w-20 transition-transform active:scale-95\">\n        <i class=\"ph ph-list-dashes text-2xl mb-1\"></i><span class=\"text-[10px] font-bold\">Riwayat</span>\n    </button>\n</nav>\n\n<main class=\"flex-1 relative overflow-y-auto pb-28 md:pb-0 scroll-smooth\">\n    <!-- Mobile header -->\n    <header class=\"md:hidden liquid-glass px-5 py-4 flex items-center justify-between sticky top-0 z-30 pt-safe\">\n        <div class=\"flex items-center gap-2.5\">\n            <div class=\"w-9 h-9 rounded-xl bg-gradient-to-br from-indigo-500 to-purple-500 flex items-center justify-center text-white shadow-md\">\n                <i class=\"ph-fill ph-wallet text-lg\"></i>\n            </div>\n            <h1 class=\"font-bold text-lg text-slate-800 tracking-tight\">RionsTracker</h1>\n        </div>\n        <div class=\"flex items-center gap-2\">\n            <button onclick=\"logout()\" class=\"w-9 h-9 flex items-center justify-center rounded-full bg-white/50 text-rose-500 hover:bg-rose-50 active:scale-95 transition-all\" title=\"Logout\">\n                <i class=\"ph-bold ph-sign-out text-xl\"></i>\n            </button>\n            <button onclick=\"openCategoryModal()\" class=\"w-9 h-9 flex items-center justify-center rounded-full bg-white/50 text-slate-600 hover:bg-white active:scale-95 transition-all\">\n                <i class=\"ph ph-tag text-xl\"></i>\n            </button>\n            <button onclick=\"openBudgetModal()\" class=\"w-9 h-9 flex items-center justify-center rounded-full bg-white/50 text-slate-600 hover:bg-white active:scale-95 transition-all\">\n                <i class=\"ph ph-target text-xl\"></i>\n            </button>\n        </div>\n    </header>\n\n    <!-- DASHBOARD VIEW -->\n    <div id=\"view-dashboard\" class=\"p-5 md:p-10 max-w-7xl mx-auto fade-in\">\n        <div class=\"hidden md:flex justify-between items-end mb-8 pt-safe\">\n            <div>\n                <h2 class=\"text-4xl font-extrabold text-slate-800 tracking-tight\">Ringkasan</h2>\n                <p class=\"text-slate-500 font-medium mt-1\" id=\"currentDateText\">Memuat...</p>\n            </div>\n            <button onclick=\"openModal()\" class=\"bg-gradient-to-r from-indigo-500 to-purple-600 hover:from-indigo-600 hover:to-purple-700 text-white px-6 py-3.5 rounded-2xl font-bold shadow-lg shadow-indigo-500/30 transition-all flex items-center gap-2 hover:-translate-y-0.5 active:translate-y-0\">\n                <i class=\"ph ph-plus-circle text-xl\"></i> Tambah Transaksi\n            </button>\n        </div>\n\n        <!-- Summary cards -->\n        <div class=\"grid grid-cols-1 lg:grid-cols-3 gap-5 mb-8\">\n            <div class=\"liquid-glass-dark rounded-3xl p-7 text-white glass-shine anim-float relative overflow-hidden\" style=\"animation-delay:0s\">\n                <div class=\"absolute -right-4 -bottom-4 text-white/10 text-9xl rotate-12 pointer-events-none\"><i class=\"ph-fill ph-wallet\"></i></div>\n                <div class=\"relative z-10\">\n                    <p class=\"text-indigo-100 font-medium text-sm mb-1\">Total Saldo Bersih</p>\n                    <h3 class=\"text-3xl lg:text-4xl font-extrabold tracking-tight\" id=\"totalBalance\">Rp 0</h3>\n                    <div id=\"balanceWarningContainer\" class=\"hidden mt-3 w-fit\">\n                        <span id=\"balanceWarningBadge\" class=\"flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-bold border\">\n                            <i class=\"ph-fill ph-warning\"></i><span id=\"balanceWarningText\">Awas, saldo mendekati 0!</span>\n                        </span>\n                    </div>\n                    <div class=\"mt-6 pt-4 border-t border-white/20 flex justify-between text-sm font-medium text-indigo-100\">\n                        <span class=\"flex items-center gap-1\"><i class=\"ph ph-chart-pie-slice shrink-0\"></i> Status Kas</span>\n                        <span class=\"bg-white/20 px-2.5 py-1 rounded-lg\" id=\"netSavingsRate\">0% Hemat</span>\n                    </div>\n                </div>\n            </div>\n            <div class=\"liquid-glass rounded-3xl p-6 flex flex-col justify-between glass-shine anim-float\" style=\"animation-delay:-2s\">\n                <div class=\"flex items-center gap-4\">\n                    <div class=\"w-14 h-14 rounded-2xl bg-gradient-to-br from-emerald-400 to-emerald-500 flex items-center justify-center text-white shadow-lg shrink-0\">\n                        <i class=\"ph-bold ph-trend-up text-2xl\"></i>\n                    </div>\n                    <div>\n                        <p class=\"text-slate-500 text-sm font-semibold\">Pemasukan</p>\n                        <h3 class=\"text-2xl font-bold text-slate-800 mt-0.5\" id=\"totalIncome\">Rp 0</h3>\n                    </div>\n                </div>\n                <div class=\"mt-4 pt-3 border-t border-slate-200/50\"><p class=\"text-xs font-medium text-slate-400\">Total akumulasi pemasukan</p></div>\n            </div>\n            <div class=\"liquid-glass rounded-3xl p-6 flex flex-col justify-between glass-shine anim-float\" style=\"animation-delay:-4s\">\n                <div class=\"flex items-center gap-4\">\n                    <div class=\"w-14 h-14 rounded-2xl bg-gradient-to-br from-rose-400 to-rose-500 flex items-center justify-center text-white shadow-lg shrink-0\">\n                        <i class=\"ph-bold ph-trend-down text-2xl\"></i>\n                    </div>\n                    <div>\n                        <p class=\"text-slate-500 text-sm font-semibold\">Pengeluaran</p>\n                        <h3 class=\"text-2xl font-bold text-slate-800 mt-0.5\" id=\"totalExpense\">Rp 0</h3>\n                    </div>\n                </div>\n                <div class=\"mt-4 pt-3 border-t border-slate-200/50\"><p class=\"text-xs font-medium text-slate-400\">Total akumulasi pengeluaran</p></div>\n            </div>\n        </div>\n\n        <!-- Budget progress -->\n        <div class=\"liquid-glass rounded-3xl p-6 mb-8 glass-shine\">\n            <div class=\"flex flex-col md:flex-row md:items-end justify-between gap-4 mb-4\">\n                <div>\n                    <div class=\"flex items-center gap-2 mb-1\">\n                        <div class=\"p-1.5 bg-indigo-100 text-indigo-600 rounded-lg\"><i class=\"ph-bold ph-target\"></i></div>\n                        <h3 class=\"text-lg font-bold text-slate-800\">Target Anggaran Bulanan</h3>\n                    </div>\n                    <p class=\"text-slate-500 text-sm\" id=\"budgetSubtext\">Pengeluaran dibanding batas maksimal</p>\n                </div>\n                <div class=\"text-left md:text-right flex flex-wrap items-baseline gap-1\">\n                    <span class=\"text-2xl font-extrabold text-slate-800\" id=\"budgetSpentText\">Rp 0</span>\n                    <span class=\"text-slate-400 text-sm font-medium\" id=\"budgetTotalText\">/ Rp 0</span>\n                </div>\n            </div>\n            <div class=\"w-full bg-slate-200/60 rounded-full h-4 overflow-hidden shadow-inner\">\n                <div id=\"budgetProgressBar\" class=\"bg-indigo-500 h-full rounded-full transition-all duration-700\" style=\"width:0%\"></div>\n            </div>\n            <div class=\"flex justify-between items-center mt-3\">\n                <p id=\"budgetWarningText\" class=\"text-xs font-bold hidden\"></p>\n                <button onclick=\"openBudgetModal()\" class=\"text-xs font-bold text-indigo-600 hover:underline bg-indigo-500/10 px-3 py-1.5 rounded-lg ml-auto transition-colors\">Sesuaikan Target</button>\n            </div>\n        </div>\n\n        <!-- Charts -->\n        <div class=\"grid grid-cols-1 lg:grid-cols-3 gap-6 mb-8\">\n            <div class=\"liquid-glass rounded-3xl p-6 lg:col-span-2 glass-shine\">\n                <h3 class=\"text-lg font-bold text-slate-800 flex items-center gap-2 mb-6\"><i class=\"ph-bold ph-chart-line-up text-indigo-500\"></i> Tren Keuangan (6 Bulan)</h3>\n                <div class=\"relative h-64 w-full\"><canvas id=\"trendChart\"></canvas></div>\n            </div>\n            <div class=\"liquid-glass rounded-3xl p-6 glass-shine\">\n                <h3 class=\"text-lg font-bold text-slate-800 mb-6 flex items-center gap-2\"><i class=\"ph-bold ph-pie-chart text-indigo-500\"></i> Kategori</h3>\n                <div class=\"relative h-56 w-full flex justify-center\"><canvas id=\"expenseChart\"></canvas></div>\n                <div id=\"emptyChartMessage\" class=\"hidden flex-col items-center justify-center h-48 text-slate-400 text-center\">\n                    <i class=\"ph ph-chart-polar text-4xl mb-2 opacity-50\"></i><p class=\"text-sm font-medium\">Belum ada data</p>\n                </div>\n            </div>\n        </div>\n\n        <!-- Recent transactions -->\n        <div class=\"liquid-glass rounded-3xl overflow-hidden mb-8 glass-shine\">\n            <div class=\"p-6 border-b border-white/50 flex justify-between items-center bg-white/30\">\n                <h3 class=\"text-lg font-bold text-slate-800\">Transaksi Terakhir</h3>\n                <button onclick=\"switchView('transactions')\" class=\"text-indigo-600 text-sm font-bold bg-white/50 px-4 py-2 rounded-xl hover:bg-white transition-colors\">Lihat Semua</button>\n            </div>\n            <div class=\"overflow-x-auto\">\n                <table class=\"w-full text-left border-collapse\">\n                    <tbody id=\"recentTransactionsList\" class=\"divide-y divide-slate-200/50 text-sm\"></tbody>\n                </table>\n            </div>\n        </div>\n    </div>\n\n    <!-- TRANSACTIONS VIEW -->\n    <div id=\"view-transactions\" class=\"p-5 md:p-10 max-w-6xl mx-auto hidden-view fade-in\">\n        <div class=\"flex flex-col md:flex-row md:items-center justify-between gap-4 mb-6 pt-safe\">\n            <div>\n                <h2 class=\"text-3xl font-extrabold text-slate-800 tracking-tight\">Semua Riwayat</h2>\n                <p class=\"text-slate-500 font-medium text-sm mt-1\">Kelola dan telusuri transaksi Anda</p>\n            </div>\n            <button onclick=\"openModal()\" class=\"bg-indigo-500 hover:bg-indigo-600 text-white px-5 py-3 rounded-2xl font-bold shadow-lg shadow-indigo-500/30 transition-all flex items-center gap-2 self-start md:self-auto active:scale-95\">\n                <i class=\"ph ph-plus text-lg\"></i> Tambah\n            </button>\n        </div>\n        <div class=\"liquid-glass p-3 rounded-2xl mb-6 flex flex-col md:flex-row gap-3 justify-between items-center\">\n            <div class=\"relative w-full md:w-80\">\n                <i class=\"ph-bold ph-magnifying-glass absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 text-lg\"></i>\n                <input type=\"text\" id=\"searchInput\" oninput=\"debounceSearch()\" placeholder=\"Cari catatan atau kategori...\"\n                    class=\"w-full pl-11 pr-4 py-3 bg-white/60 border border-white/80 rounded-xl text-sm font-medium focus:outline-none focus:ring-2 focus:ring-indigo-500/50 shadow-sm transition-all placeholder:text-slate-400\">\n            </div>\n            <div class=\"bg-slate-200/50 p-1 rounded-xl flex text-xs font-bold w-full md:w-auto\">\n                <button id=\"filterAll\" onclick=\"setFilter('all')\" class=\"flex-1 md:flex-none px-5 py-2.5 rounded-lg bg-white text-slate-800 shadow-sm transition-all\">Semua</button>\n                <button id=\"filterIncome\" onclick=\"setFilter('income')\" class=\"flex-1 md:flex-none px-5 py-2.5 rounded-lg text-slate-500 hover:text-slate-800 transition-all\">Pemasukan</button>\n                <button id=\"filterExpense\" onclick=\"setFilter('expense')\" class=\"flex-1 md:flex-none px-5 py-2.5 rounded-lg text-slate-500 hover:text-slate-800 transition-all\">Pengeluaran</button>\n            </div>\n        </div>\n        <div class=\"liquid-glass rounded-3xl overflow-hidden mb-20 md:mb-8 glass-shine\">\n            <div class=\"overflow-x-auto\">\n                <table class=\"w-full text-left border-collapse\">\n                    <thead class=\"bg-white/40 border-b border-white/60\">\n                        <tr class=\"text-slate-500 text-[11px] font-bold uppercase tracking-wider\">\n                            <th class=\"p-4 pl-6\">Detail Transaksi</th>\n                            <th class=\"p-4 hidden sm:table-cell\">Catatan</th>\n                            <th class=\"p-4\">Tanggal</th>\n                            <th class=\"p-4 text-right\">Jumlah</th>\n                            <th class=\"p-4 pr-6 text-center\">Aksi</th>\n                        </tr>\n                    </thead>\n                    <tbody id=\"fullTransactionsList\" class=\"divide-y divide-slate-200/50 text-sm\"></tbody>\n                </table>\n            </div>\n            <div id=\"emptyTransactionsState\" class=\"hidden flex-col items-center justify-center p-16 text-slate-400\">\n                <div class=\"w-20 h-20 bg-slate-200/50 rounded-full flex items-center justify-center mb-4\"><i class=\"ph-fill ph-receipt text-4xl text-slate-400\"></i></div>\n                <p class=\"text-lg font-bold text-slate-600\">Tidak ada data</p>\n                <p class=\"text-sm text-slate-500 mt-1 text-center\">Belum ada transaksi yang sesuai filter.</p>\n            </div>\n        </div>\n    </div>\n</main>\n\n<!-- MODAL: ADD / EDIT TRANSACTION -->\n<div id=\"transactionModal\" class=\"fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-[60] hidden flex justify-center items-center p-4 transition-opacity opacity-0\">\n    <div class=\"absolute inset-0 z-0\" onclick=\"closeModal()\"></div>\n    <div class=\"liquid-glass w-full max-w-md rounded-3xl shadow-2xl relative z-10 transform scale-95 transition-transform duration-300 flex flex-col max-h-[90vh]\">\n        <div class=\"p-5 border-b border-white/50 flex justify-between items-center shrink-0\">\n            <h3 class=\"text-xl font-extrabold text-slate-800\" id=\"modalTitle\">Tambah Transaksi</h3>\n            <button onclick=\"closeModal()\" class=\"w-9 h-9 flex items-center justify-center rounded-full bg-slate-200/50 text-slate-500 hover:bg-slate-300/50 transition-colors active:scale-90\">\n                <i class=\"ph-bold ph-x text-lg\"></i>\n            </button>\n        </div>\n        <div class=\"p-6 overflow-y-auto space-y-5\">\n            <form id=\"transactionForm\" class=\"space-y-5\">\n                <input type=\"hidden\" id=\"editTxId\" value=\"\">\n                <div class=\"grid grid-cols-2 gap-3 p-1.5 bg-slate-200/50 rounded-2xl\">\n                    <label class=\"cursor-pointer\">\n                        <input type=\"radio\" name=\"txType\" value=\"expense\" class=\"peer sr-only\" checked onchange=\"updateCategoryOptions()\">\n                        <div class=\"py-3 rounded-xl text-sm font-bold text-slate-500 text-center peer-checked:bg-white peer-checked:text-rose-600 peer-checked:shadow transition-all\">Pengeluaran</div>\n                    </label>\n                    <label class=\"cursor-pointer\">\n                        <input type=\"radio\" name=\"txType\" value=\"income\" class=\"peer sr-only\" onchange=\"updateCategoryOptions()\">\n                        <div class=\"py-3 rounded-xl text-sm font-bold text-slate-500 text-center peer-checked:bg-white peer-checked:text-emerald-600 peer-checked:shadow transition-all\">Pemasukan</div>\n                    </label>\n                </div>\n                <div>\n                    <label class=\"block text-xs font-bold text-slate-600 mb-1.5\">Nominal (Rp)</label>\n                    <div class=\"relative\">\n                        <span class=\"absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 font-bold\">Rp</span>\n                        <input type=\"text\" id=\"txAmount\" inputmode=\"numeric\" oninput=\"formatInputAmount(this)\" required\n                            class=\"w-full pl-12 pr-4 py-3.5 bg-white/70 border border-white/80 rounded-2xl focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition-all text-xl font-extrabold text-slate-800 shadow-sm\" placeholder=\"0\">\n                    </div>\n                </div>\n                <div class=\"grid grid-cols-2 gap-4\">\n                    <div>\n                        <label class=\"block text-xs font-bold text-slate-600 mb-1.5\">Kategori</label>\n                        <select id=\"txCategory\" required class=\"w-full px-4 py-3.5 bg-white/70 border border-white/80 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none text-slate-800 text-sm font-semibold shadow-sm appearance-none cursor-pointer\"></select>\n                    </div>\n                    <div>\n                        <label class=\"block text-xs font-bold text-slate-600 mb-1.5\">Tanggal</label>\n                        <input type=\"date\" id=\"txDate\" required class=\"w-full px-4 py-3.5 bg-white/70 border border-white/80 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none text-slate-800 text-sm font-semibold shadow-sm\">\n                    </div>\n                </div>\n                <div>\n                    <label class=\"block text-xs font-bold text-slate-600 mb-1.5\">Catatan (Opsional)</label>\n                    <input type=\"text\" id=\"txNote\" class=\"w-full px-4 py-3.5 bg-white/70 border border-white/80 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none text-slate-800 text-sm font-semibold shadow-sm placeholder:text-slate-400 placeholder:font-normal\" placeholder=\"Misal: Beli bahan makanan...\">\n                </div>\n                <button type=\"submit\" id=\"btnSubmitTx\" class=\"w-full py-4 mt-2 bg-gradient-to-r from-indigo-500 to-purple-600 hover:from-indigo-600 hover:to-purple-700 text-white rounded-2xl font-bold shadow-[0_8px_20px_rgba(79,70,229,0.3)] transition-transform active:scale-[0.98] flex items-center justify-center gap-2\">\n                    <i class=\"ph-bold ph-cloud-arrow-up text-xl\"></i><span>Simpan Transaksi</span>\n                </button>\n            </form>\n        </div>\n    </div>\n</div>\n\n<!-- MODAL: DELETE CONFIRM -->\n<div id=\"deleteModal\" class=\"fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-[60] hidden flex justify-center items-center p-4 transition-opacity opacity-0\">\n    <div class=\"absolute inset-0 z-0\" onclick=\"closeDeleteModal()\"></div>\n    <div class=\"liquid-glass w-full max-w-sm rounded-3xl shadow-2xl p-6 text-center relative z-10 transform scale-95 transition-transform duration-300\">\n        <div class=\"w-16 h-16 bg-rose-100 text-rose-500 rounded-2xl flex items-center justify-center mx-auto mb-4 border border-white shadow-sm\"><i class=\"ph-fill ph-trash text-3xl\"></i></div>\n        <h3 class=\"text-xl font-extrabold text-slate-800 mb-2\">Hapus Transaksi?</h3>\n        <p class=\"text-sm font-medium text-slate-500 mb-6\">Data ini akan dihapus dari server secara permanen.</p>\n        <div class=\"flex gap-3\">\n            <button onclick=\"closeDeleteModal()\" class=\"flex-1 py-3.5 bg-slate-200/50 text-slate-600 font-bold rounded-2xl hover:bg-slate-300/50 transition-colors\">Batal</button>\n            <button id=\"btnConfirmDelete\" class=\"flex-1 py-3.5 bg-rose-500 text-white font-bold rounded-2xl shadow-lg shadow-rose-500/30 active:scale-95 transition-transform\">Ya, Hapus</button>\n        </div>\n    </div>\n</div>\n\n<!-- MODAL: BUDGET -->\n<div id=\"budgetModal\" class=\"fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-[60] hidden flex justify-center items-center p-4 transition-opacity opacity-0\">\n    <div class=\"absolute inset-0 z-0\" onclick=\"closeBudgetModal()\"></div>\n    <div class=\"liquid-glass w-full max-w-sm rounded-3xl shadow-2xl p-6 relative z-10 transform scale-95 transition-transform duration-300\">\n        <div class=\"flex justify-between items-center mb-4 pb-3 border-b border-white/50\">\n            <div class=\"flex items-center gap-2\">\n                <div class=\"p-2 bg-indigo-100 text-indigo-600 rounded-xl\"><i class=\"ph-bold ph-target text-lg\"></i></div>\n                <h3 class=\"text-lg font-extrabold text-slate-800\">Target Anggaran</h3>\n            </div>\n            <button onclick=\"closeBudgetModal()\" class=\"w-8 h-8 flex items-center justify-center rounded-full bg-slate-200/50 text-slate-500 hover:bg-slate-300/50\"><i class=\"ph-bold ph-x\"></i></button>\n        </div>\n        <form onsubmit=\"saveBudgetTarget(event)\" class=\"space-y-4\">\n            <div>\n                <label class=\"block text-xs font-bold text-slate-600 mb-1.5\">Batas Pengeluaran Bulanan (Rp)</label>\n                <input type=\"text\" id=\"inputBudgetValue\" inputmode=\"numeric\" oninput=\"formatInputAmount(this)\" required class=\"w-full px-4 py-3 bg-white/70 border border-white/80 rounded-xl text-lg font-bold outline-none focus:ring-2 focus:ring-indigo-500 shadow-sm\">\n            </div>\n            <button type=\"submit\" class=\"w-full py-3 bg-indigo-500 text-white font-bold rounded-xl shadow-md shadow-indigo-500/30 active:scale-95 transition-all text-sm\">Simpan Target</button>\n        </form>\n    </div>\n</div>\n\n<!-- MODAL: CATEGORIES -->\n<div id=\"categoryModal\" class=\"fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-[60] hidden flex justify-center items-center p-4 transition-opacity opacity-0\">\n    <div class=\"absolute inset-0 z-0\" onclick=\"closeCategoryModal()\"></div>\n    <div class=\"liquid-glass w-full max-w-md rounded-3xl shadow-2xl relative z-10 transform scale-95 transition-transform duration-300 flex flex-col max-h-[85vh]\">\n        <div class=\"p-5 border-b border-white/50 flex justify-between items-center shrink-0\">\n            <div class=\"flex items-center gap-2\">\n                <div class=\"p-2 bg-indigo-100 text-indigo-600 rounded-xl\"><i class=\"ph-bold ph-tag text-lg\"></i></div>\n                <h3 class=\"text-lg font-extrabold text-slate-800\">Kelola Kategori</h3>\n            </div>\n            <button onclick=\"closeCategoryModal()\" class=\"w-8 h-8 flex items-center justify-center rounded-full bg-slate-200/50 text-slate-500 hover:bg-slate-300/50\"><i class=\"ph-bold ph-x\"></i></button>\n        </div>\n        <div class=\"p-6 overflow-y-auto\">\n            <form id=\"addCategoryForm\" onsubmit=\"addNewCategory(event)\" class=\"space-y-4 mb-6\">\n                <div class=\"grid grid-cols-2 gap-3\">\n                    <div>\n                        <label class=\"block text-xs font-bold text-slate-600 mb-1\">Tipe</label>\n                        <select id=\"newCatType\" class=\"w-full px-3 py-2.5 bg-white/70 border border-white/80 rounded-xl text-sm font-semibold outline-none focus:ring-2 focus:ring-indigo-500\">\n                            <option value=\"expense\">Pengeluaran</option><option value=\"income\">Pemasukan</option>\n                        </select>\n                    </div>\n                    <div>\n                        <label class=\"block text-xs font-bold text-slate-600 mb-1\">Nama Kategori</label>\n                        <input type=\"text\" id=\"newCatName\" required placeholder=\"Misal: Langganan\" class=\"w-full px-3 py-2.5 bg-white/70 border border-white/80 rounded-xl text-sm font-semibold outline-none focus:ring-2 focus:ring-indigo-500 placeholder:font-normal\">\n                    </div>\n                </div>\n                <button type=\"submit\" class=\"w-full py-3 bg-indigo-500 text-white font-bold rounded-xl shadow-md shadow-indigo-500/30 active:scale-95 transition-all text-sm flex items-center justify-center gap-2\">\n                    <i class=\"ph-bold ph-plus\"></i> Tambah Kategori\n                </button>\n            </form>\n            <h4 class=\"text-xs font-extrabold text-slate-400 uppercase tracking-wider mb-2\">Kategori Saat Ini</h4>\n            <div id=\"categoryListContainer\" class=\"space-y-2\"></div>\n        </div>\n    </div>\n</div>\n\n<!-- TOAST -->\n<div id=\"toastContainer\" class=\"fixed top-0 left-1/2 -translate-x-1/2 pt-4 z-[80] flex flex-col gap-3 w-full max-w-sm px-4 pointer-events-none\"></div>\n\n<script>\n// ═══════════════════════════════════════════════════════════════\n// STATE\n// ═══════════════════════════════════════════════════════════════\nlet API_URL = localStorage.getItem('rions_api_url') || 'http://localhost:3001';\nlet authToken = localStorage.getItem('rions_token') || null;\nlet currentUsername = localStorage.getItem('rions_username') || null;\nlet transactions = [];\nlet categories = { expense: [], income: [] };\nlet summary = { income: 0, expense: 0, balance: 0, byCategory: [], trend: [] };\nlet monthlyBudget = 5000000;\nlet currentView = 'dashboard';\nlet currentFilter = 'all';\nlet searchQuery = '';\nlet pendingDeleteId = null;\nlet searchTimeout = null;\nlet charts = { trend: null, expense: null };\nlet authTab = 'login';\n\nconst today = new Date().toISOString().split('T')[0];\n\n// ═══════════════════════════════════════════════════════════════\n// API HELPER\n// ═══════════════════════════════════════════════════════════════\nasync function api(method, path, body = null) {\n    const opts = {\n        method,\n        headers: { 'Content-Type': 'application/json', ...(authToken ? { 'Authorization': `Bearer ${authToken}` } : {}) }\n    };\n    if (body) opts.body = JSON.stringify(body);\n    try {\n        const res = await fetch('/api?r=' + encodeURIComponent(path.replace(/^\\/api/, '')), opts);\n        const data = await res.json();\n        if (!res.ok) throw new Error(data.error || `HTTP ${res.status}`);\n        return data;\n    } catch (e) {\n        if (e.message.includes('fetch') || e.message.includes('Failed')) {\n            showToast('Tidak dapat terhubung ke server. Pastikan backend berjalan.', 'error');\n        }\n        throw e;\n    }\n}\n\n// ═══════════════════════════════════════════════════════════════\n// AUTH\n// ═══════════════════════════════════════════════════════════════\nfunction setAuthTab(tab) {\n    authTab = tab;\n    const isLogin = tab === 'login';\n    document.getElementById('tabLoginBtn').className = isLogin\n        ? 'flex-1 py-2.5 rounded-xl bg-white text-slate-800 shadow-sm transition-all'\n        : 'flex-1 py-2.5 rounded-xl text-slate-500 hover:text-slate-800 transition-all';\n    document.getElementById('tabRegisterBtn').className = !isLogin\n        ? 'flex-1 py-2.5 rounded-xl bg-white text-slate-800 shadow-sm transition-all'\n        : 'flex-1 py-2.5 rounded-xl text-slate-500 hover:text-slate-800 transition-all';\n    document.getElementById('authSubmitLabel').textContent = isLogin ? 'Masuk' : 'Buat Akun';\n    document.getElementById('authSwitchText').textContent = isLogin ? 'Belum punya akun?' : 'Sudah punya akun?';\n    document.getElementById('authSwitchBtn').textContent = isLogin ? 'Daftar' : 'Masuk';\n    document.getElementById('authSwitchBtn').onclick = () => setAuthTab(isLogin ? 'register' : 'login');\n    document.getElementById('authError').classList.add('hidden');\n}\n\nasync function handleAuthSubmit(e) {\n    e.preventDefault();\n    \n    const username = document.getElementById('authUsername').value.trim().toLowerCase();\n    const password = document.getElementById('authPassword').value;\n    const errEl = document.getElementById('authError');\n    const btn = document.getElementById('authSubmitBtn');\n\n    errEl.classList.add('hidden');\n    btn.disabled = true;\n    btn.innerHTML = '<i class=\"ph ph-spinner text-lg spin\"></i><span>Memproses...</span>';\n\n    try {\n        const endpoint = authTab === 'login' ? '/api/auth/login' : '/api/auth/register';\n        const data = await api('POST', endpoint, { username, password });\n        authToken = data.token;\n        currentUsername = data.username;\n        if (data.budget) monthlyBudget = data.budget;\n        localStorage.setItem('rions_token', authToken);\n        localStorage.setItem('rions_username', currentUsername);\n        showAuthPage(false);\n        await initAppData();\n        showToast(authTab === 'login' ? `Selamat datang, @${currentUsername}!` : `Akun @${currentUsername} berhasil dibuat!`);\n    } catch (err) {\n        errEl.textContent = err.message;\n        errEl.classList.remove('hidden');\n    } finally {\n        btn.disabled = false;\n        btn.innerHTML = `<i class=\"ph-bold ph-sign-in text-lg\"></i><span>${authTab === 'login' ? 'Masuk' : 'Buat Akun'}</span>`;\n    }\n}\n\nfunction togglePassVis() {\n    const input = document.getElementById('authPassword');\n    const icon = document.getElementById('passEyeIcon');\n    if (input.type === 'password') { input.type = 'text'; icon.className = 'ph ph-eye-slash text-lg'; }\n    else { input.type = 'password'; icon.className = 'ph ph-eye text-lg'; }\n}\n\nfunction showAuthPage(show) {\n    const authPage = document.getElementById('authPage');\n    const sidebar = document.getElementById('sidebarEl');\n    const main = document.querySelector('main');\n    const mobileNav = document.querySelector('nav.md\\\\:hidden');\n    if (show) {\n        authPage.style.display = 'flex';\n        if (sidebar) sidebar.style.display = 'none';\n        if (main) main.style.display = 'none';\n        if (mobileNav) mobileNav.style.display = 'none';\n    } else {\n        authPage.style.display = 'none';\n        if (sidebar) sidebar.style.display = '';\n        if (main) main.style.display = '';\n        if (mobileNav) mobileNav.style.display = '';\n    }\n}\n\nasync function logout() {\n    authToken = null; currentUsername = null;\n    localStorage.removeItem('rions_token');\n    localStorage.removeItem('rions_username');\n    transactions = []; categories = { expense: [], income: [] };\n    if (charts.trend) { charts.trend.destroy(); charts.trend = null; }\n    if (charts.expense) { charts.expense.destroy(); charts.expense = null; }\n    showAuthPage(true);\n    showToast('Berhasil logout');\n}\n\n// ═══════════════════════════════════════════════════════════════\n// INIT\n// ═══════════════════════════════════════════════════════════════\nasync function initApp() {\n    if (authToken && currentUsername) {\n        showAuthPage(false);\n        try {\n            await initAppData();\n        } catch {\n            // token expired\n            showAuthPage(true);\n        }\n    } else {\n        showAuthPage(true);\n    }\n}\n\nasync function initAppData() {\n    document.getElementById('sidebarUsername').textContent = `@${currentUsername}`;\n    await Promise.all([loadCategories(), loadTransactions(), loadSummary()]);\n    const me = await api('GET', '/api/auth/me').catch(() => null);\n    if (me) { monthlyBudget = me.monthly_budget; }\n    renderApp();\n    document.getElementById('currentDateText').textContent = new Date().toLocaleDateString('id-ID', { month: 'long', year: 'numeric' });\n}\n\n// ═══════════════════════════════════════════════════════════════\n// DATA LOADING\n// ═══════════════════════════════════════════════════════════════\nasync function loadTransactions(params = '') {\n    transactions = await api('GET', `/api/transactions${params}`);\n}\n\nasync function loadSummary() {\n    summary = await api('GET', '/api/transactions/summary');\n}\n\nasync function loadCategories() {\n    const cats = await api('GET', '/api/categories');\n    categories = { expense: [], income: [] };\n    cats.forEach(c => {\n        const obj = { id: c.name, icon: c.icon, color: c.color, bg: c.bg, hex: c.hex, custom: !!c.is_custom, dbId: c.id };\n        if (c.type === 'expense') categories.expense.push(obj);\n        else categories.income.push(obj);\n    });\n}\n\n// ═══════════════════════════════════════════════════════════════\n// FORMATTERS\n// ═══════════════════════════════════════════════════════════════\nconst formatRupiah = (n) => new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', minimumFractionDigits: 0 }).format(n);\nconst formatDate = (d) => !d ? '-' : new Date(d).toLocaleDateString('id-ID', { day: 'numeric', month: 'short', year: 'numeric' });\nwindow.formatInputAmount = function(input) {\n    let v = input.value.replace(/\\D/g, '');\n    input.value = v.replace(/\\B(?=(\\d{3})+(?!\\d))/g, '.');\n};\nconst getCategoryInfo = (type, catId) => {\n    const list = categories[type] || categories.expense;\n    return list.find(c => c.id === catId) || list[list.length - 1] || { icon:'ph-tag', color:'text-slate-500', bg:'bg-slate-200/80' };\n};\n\n// ═══════════════════════════════════════════════════════════════\n// RENDER\n// ═══════════════════════════════════════════════════════════════\nfunction renderApp() {\n    updateSummaryCards();\n    updateBudgetUI();\n    if (currentView === 'dashboard') {\n        document.getElementById('view-dashboard').classList.remove('hidden-view');\n        document.getElementById('view-transactions').classList.add('hidden-view');\n        renderCharts(); renderRecentTransactions(); updateNavStyles('dashboard');\n    } else {\n        document.getElementById('view-dashboard').classList.add('hidden-view');\n        document.getElementById('view-transactions').classList.remove('hidden-view');\n        renderFullTransactions(); updateNavStyles('transactions');\n    }\n}\n\nfunction updateSummaryCards() {\n    const { income, expense, balance } = summary;\n    document.getElementById('totalBalance').textContent = formatRupiah(balance);\n    document.getElementById('totalIncome').textContent = formatRupiah(income);\n    document.getElementById('totalExpense').textContent = formatRupiah(expense);\n    const rate = income > 0 ? Math.max(0, Math.round(((income - expense) / income) * 100)) : 0;\n    document.getElementById('netSavingsRate').textContent = `${rate}% Hemat`;\n\n    const warnEl = document.getElementById('balanceWarningContainer');\n    const badge = document.getElementById('balanceWarningBadge');\n    const warnTxt = document.getElementById('balanceWarningText');\n    if (transactions.length > 0) {\n        if (balance <= 0) {\n            warnEl.classList.remove('hidden');\n            badge.className = 'flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-bold border bg-rose-500/20 text-rose-200 border-rose-500/30';\n            warnTxt.textContent = 'Saldo habis / minus!';\n        } else if (income > 0 && balance <= income * 0.1) {\n            warnEl.classList.remove('hidden');\n            badge.className = 'flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-bold border bg-amber-400/20 text-amber-200 border-amber-400/30';\n            warnTxt.textContent = 'Saldo mendekati Rp 0!';\n        } else { warnEl.classList.add('hidden'); }\n    } else { warnEl.classList.add('hidden'); }\n}\n\nfunction updateBudgetUI() {\n    const exp = summary.expense || 0;\n    const pct = monthlyBudget > 0 ? Math.min(100, Math.round((exp / monthlyBudget) * 100)) : 0;\n    const bar = document.getElementById('budgetProgressBar');\n    bar.style.width = `${pct}%`;\n    bar.className = `h-full rounded-full transition-all duration-700 ${pct >= 100 ? 'bg-rose-500' : pct >= 80 ? 'bg-amber-400' : 'bg-indigo-500'}`;\n    document.getElementById('budgetSpentText').textContent = formatRupiah(exp);\n    document.getElementById('budgetTotalText').textContent = `/ ${formatRupiah(monthlyBudget)}`;\n    const warn = document.getElementById('budgetWarningText');\n    if (pct >= 100) { warn.textContent = '⚠️ Anggaran bulanan telah terlampaui!'; warn.className = 'text-xs font-bold text-rose-600'; warn.classList.remove('hidden'); }\n    else if (pct >= 80) { warn.textContent = `🔶 ${pct}% anggaran terpakai, berhati-hati!`; warn.className = 'text-xs font-bold text-amber-600'; warn.classList.remove('hidden'); }\n    else { warn.classList.add('hidden'); }\n}\n\nfunction renderCharts() {\n    // Trend chart\n    const trendCtx = document.getElementById('trendChart').getContext('2d');\n    if (charts.trend) charts.trend.destroy();\n    const trend = summary.trend || [];\n    const labels = trend.map(r => { const [y,m] = r.month.split('-'); return new Date(y, m-1).toLocaleDateString('id-ID',{month:'short',year:'2-digit'}); });\n    charts.trend = new Chart(trendCtx, {\n        type: 'line',\n        data: {\n            labels,\n            datasets: [\n                { label:'Pemasukan', data: trend.map(r=>r.income), borderColor:'#10b981', backgroundColor:'rgba(16,185,129,0.1)', borderWidth:2.5, tension:0.4, fill:true, pointRadius:4, pointHoverRadius:6 },\n                { label:'Pengeluaran', data: trend.map(r=>r.expense), borderColor:'#f43f5e', backgroundColor:'rgba(244,63,94,0.08)', borderWidth:2.5, tension:0.4, fill:true, pointRadius:4, pointHoverRadius:6 }\n            ]\n        },\n        options: { responsive:true, maintainAspectRatio:false, interaction:{intersect:false,mode:'index'}, plugins:{legend:{position:'top',labels:{font:{family:'Inter',size:11},usePointStyle:true,boxWidth:8}}}, scales:{x:{grid:{display:false},ticks:{font:{family:'Inter',size:10}}},y:{grid:{color:'rgba(0,0,0,0.05)'},ticks:{callback:v=>formatRupiah(v).replace('Rp','Rp').replace(/\\B(?=(\\d{3})+(?!\\d))/g,'.'),font:{family:'Inter',size:10}},beginAtZero:true}} }\n    });\n\n    // Expense donut\n    const expCtx = document.getElementById('expenseChart').getContext('2d');\n    if (charts.expense) charts.expense.destroy();\n    const byCat = (summary.byCategory || []).filter(c => c.type === 'expense');\n    const empty = document.getElementById('emptyChartMessage');\n    if (byCat.length === 0) { empty.style.display='flex'; document.getElementById('expenseChart').style.display='none'; return; }\n    empty.style.display='none'; document.getElementById('expenseChart').style.display='block';\n    const colors = byCat.map(c => { const cat = getCategoryInfo('expense', c.category); return cat.hex || '#6366f1'; });\n    charts.expense = new Chart(expCtx, {\n        type: 'doughnut',\n        data: { labels: byCat.map(c=>c.category), datasets:[{ data: byCat.map(c=>c.total), backgroundColor: colors, borderWidth:0, hoverOffset:8 }] },\n        options: { responsive:true, maintainAspectRatio:false, cutout:'72%', plugins:{legend:{position:'bottom',labels:{font:{family:'Inter',size:11},usePointStyle:true,boxWidth:8,padding:12}}} }\n    });\n}\n\nfunction generateTransactionHTML(t, isFull) {\n    const cat = getCategoryInfo(t.type, t.category);\n    const isInc = t.type === 'income';\n    const actionHtml = isFull\n        ? `<td class=\"p-4 pr-6 text-center w-24\"><div class=\"flex items-center justify-center gap-2\"><button onclick=\"editTransaction(${t.id})\" class=\"w-8 h-8 flex items-center justify-center text-slate-400 hover:text-indigo-600 bg-white/50 hover:bg-white rounded-lg shadow-sm\"><i class=\"ph-bold ph-pencil-simple\"></i></button><button onclick=\"confirmDelete(${t.id})\" class=\"w-8 h-8 flex items-center justify-center text-slate-400 hover:text-rose-600 bg-white/50 hover:bg-white rounded-lg shadow-sm\"><i class=\"ph-bold ph-trash\"></i></button></div></td>` : '';\n    return `<tr class=\"hover:bg-white/40 transition-colors\"><td class=\"p-4 pl-6\"><div class=\"flex items-center gap-4\"><div class=\"w-12 h-12 rounded-2xl ${cat.bg} ${cat.color} flex items-center justify-center shrink-0 shadow-sm border border-white\"><i class=\"ph-fill ${cat.icon} text-2xl\"></i></div><div><p class=\"font-bold text-slate-800 text-sm\">${t.category}</p><p class=\"text-[11px] font-medium text-slate-400 sm:hidden truncate max-w-[140px] mt-0.5\">${t.note||'-'}</p></div></div></td><td class=\"p-4 hidden sm:table-cell text-slate-500 text-sm font-medium max-w-[200px] truncate\">${t.note||'-'}</td><td class=\"p-4 text-slate-500 text-xs font-semibold whitespace-nowrap\">${formatDate(t.date)}</td><td class=\"p-4 text-right font-extrabold ${isInc?'text-emerald-600':'text-slate-800'} whitespace-nowrap text-sm\">${isInc?'+':'-'} ${formatRupiah(t.amount)}</td>${actionHtml}</tr>`;\n}\n\nfunction renderRecentTransactions() {\n    const tbody = document.getElementById('recentTransactionsList');\n    const sorted = [...transactions].sort((a,b)=>new Date(b.date)-new Date(a.date)).slice(0,5);\n    tbody.innerHTML = sorted.length === 0\n        ? `<tr><td colspan=\"4\" class=\"p-10 text-center text-slate-400 font-medium\"><i class=\"ph ph-wind text-3xl mb-2 block\"></i> Belum ada aktivitas.</td></tr>`\n        : sorted.map(t=>generateTransactionHTML(t,false)).join('');\n}\n\nfunction renderFullTransactions() {\n    const tbody = document.getElementById('fullTransactionsList');\n    let filtered = currentFilter !== 'all' ? transactions.filter(t=>t.type===currentFilter) : [...transactions];\n    if (searchQuery.trim()) { const q = searchQuery.toLowerCase(); filtered = filtered.filter(t=>(t.category||'').toLowerCase().includes(q)||(t.note||'').toLowerCase().includes(q)); }\n    filtered.sort((a,b)=>new Date(b.date)-new Date(a.date));\n    const emptyState = document.getElementById('emptyTransactionsState');\n    if (filtered.length === 0) {\n        tbody.innerHTML=''; tbody.parentElement.classList.add('hidden'); emptyState.style.display='flex';\n    } else {\n        tbody.parentElement.classList.remove('hidden'); emptyState.style.display='none';\n        tbody.innerHTML = filtered.map(t=>generateTransactionHTML(t,true)).join('');\n    }\n    ['all','income','expense'].forEach(f=>{\n        const btn = document.getElementById(`filter${f.charAt(0).toUpperCase()+f.slice(1)}`);\n        btn.className = f===currentFilter ? 'flex-1 md:flex-none px-5 py-2.5 rounded-xl bg-white text-indigo-600 shadow-sm transition-all border border-white' : 'flex-1 md:flex-none px-5 py-2.5 rounded-xl text-slate-500 hover:text-slate-800 hover:bg-white/50 transition-all border border-transparent';\n    });\n}\n\n// ═══════════════════════════════════════════════════════════════\n// TRANSACTION CRUD\n// ═══════════════════════════════════════════════════════════════\ndocument.getElementById('transactionForm').addEventListener('submit', async (e) => {\n    e.preventDefault();\n    const isExpense = document.querySelector('input[name=\"txType\"][value=\"expense\"]').checked;\n    const rawAmount = document.getElementById('txAmount').value.replace(/\\./g,'');\n    const editId = document.getElementById('editTxId').value;\n    const btn = document.getElementById('btnSubmitTx');\n\n    const txData = {\n        type: isExpense ? 'expense' : 'income',\n        amount: Number(rawAmount),\n        category: document.getElementById('txCategory').value,\n        date: document.getElementById('txDate').value,\n        note: document.getElementById('txNote').value.trim()\n    };\n\n    btn.disabled = true;\n    btn.innerHTML = '<i class=\"ph ph-spinner text-xl spin\"></i><span>Menyimpan...</span>';\n    try {\n        if (editId) await api('PUT', `/api/transactions/${editId}`, txData);\n        else await api('POST', '/api/transactions', txData);\n        await Promise.all([loadTransactions(), loadSummary()]);\n        renderApp(); closeModal();\n        showToast(editId ? 'Transaksi diperbarui!' : 'Transaksi ditambahkan!');\n        if (!editId && isExpense) {\n            const b = summary.balance;\n            if (b <= 0) setTimeout(()=>showToast('Peringatan: Saldo habis atau minus!','error'),300);\n            else if (summary.income > 0 && b <= summary.income * 0.1) setTimeout(()=>showToast('Awas: Saldo mendekati Rp 0!','error'),300);\n        }\n    } catch(err) { showToast(err.message,'error'); }\n    finally { btn.disabled=false; btn.innerHTML='<i class=\"ph-bold ph-cloud-arrow-up text-xl\"></i><span>Simpan Transaksi</span>'; }\n});\n\nwindow.editTransaction = async function(id) {\n    const tx = transactions.find(t=>t.id===id);\n    if (!tx) return;\n    document.getElementById('editTxId').value = tx.id;\n    document.getElementById('modalTitle').textContent = 'Edit Transaksi';\n    document.getElementById('txAmount').value = String(tx.amount).replace(/\\B(?=(\\d{3})+(?!\\d))/g,'.');\n    document.getElementById('txDate').value = tx.date;\n    document.getElementById('txNote').value = tx.note || '';\n    document.querySelector(`input[name=\"txType\"][value=\"${tx.type}\"]`).checked = true;\n    updateCategoryOptions(); document.getElementById('txCategory').value = tx.category;\n    toggleModal('transactionModal', true);\n};\n\nwindow.confirmDelete = function(id) { pendingDeleteId = id; toggleModal('deleteModal', true); };\nwindow.closeDeleteModal = function() { pendingDeleteId = null; toggleModal('deleteModal', false); };\ndocument.getElementById('btnConfirmDelete').addEventListener('click', async () => {\n    if (!pendingDeleteId) return;\n    try {\n        await api('DELETE', `/api/transactions/${pendingDeleteId}`);\n        await Promise.all([loadTransactions(), loadSummary()]);\n        renderApp(); showToast('Transaksi dihapus');\n    } catch(err) { showToast(err.message,'error'); }\n    closeDeleteModal();\n});\n\n// ═══════════════════════════════════════════════════════════════\n// CATEGORIES CRUD\n// ═══════════════════════════════════════════════════════════════\nwindow.updateCategoryOptions = function() {\n    const type = document.querySelector('input[name=\"txType\"]:checked').value;\n    document.getElementById('txCategory').innerHTML = (categories[type]||[]).map(c=>`<option value=\"${c.id}\">${c.id}</option>`).join('');\n};\n\nfunction renderCategoryList() {\n    const container = document.getElementById('categoryListContainer');\n    if (!container) return;\n    let html = '';\n    ['expense','income'].forEach(type => {\n        html += `<div class=\"text-xs font-bold text-slate-500 mt-3 mb-1 uppercase tracking-wider\">${type==='expense'?'Pengeluaran':'Pemasukan'}</div>`;\n        (categories[type]||[]).forEach(cat => {\n            const del = cat.custom\n                ? `<button onclick=\"deleteCustomCategory(${cat.dbId})\" class=\"text-rose-500 hover:text-rose-700 p-1 rounded-lg hover:bg-rose-50 transition-colors\"><i class=\"ph-bold ph-trash\"></i></button>`\n                : `<span class=\"text-[10px] text-slate-400 bg-slate-200/50 px-2 py-0.5 rounded\">Default</span>`;\n            html += `<div class=\"flex items-center justify-between p-2.5 bg-white/50 border border-white/80 rounded-2xl\"><div class=\"flex items-center gap-3\"><div class=\"w-8 h-8 rounded-xl ${cat.bg} ${cat.color} flex items-center justify-center\"><i class=\"ph-fill ${cat.icon}\"></i></div><span class=\"text-sm font-bold text-slate-800\">${cat.id}</span></div>${del}</div>`;\n        });\n    });\n    container.innerHTML = html;\n}\n\nwindow.addNewCategory = async function(e) {\n    e.preventDefault();\n    const type = document.getElementById('newCatType').value;\n    const name = document.getElementById('newCatName').value.trim();\n    if (!name) return;\n    try {\n        await api('POST', '/api/categories', { name, type });\n        await loadCategories();\n        renderCategoryList(); updateCategoryOptions();\n        document.getElementById('newCatName').value = '';\n        showToast('Kategori ditambahkan!');\n    } catch(err) { showToast(err.message,'error'); }\n};\n\nwindow.deleteCustomCategory = async function(dbId) {\n    try {\n        await api('DELETE', `/api/categories/${dbId}`);\n        await loadCategories();\n        renderCategoryList(); updateCategoryOptions();\n        showToast('Kategori dihapus');\n    } catch(err) { showToast(err.message,'error'); }\n};\n\n// ═══════════════════════════════════════════════════════════════\n// BUDGET\n// ═══════════════════════════════════════════════════════════════\nwindow.saveBudgetTarget = async function(e) {\n    e.preventDefault();\n    const raw = document.getElementById('inputBudgetValue').value.replace(/\\./g,'');\n    const val = Number(raw);\n    if (!val) return;\n    try {\n        await api('PUT', '/api/budget', { monthly_budget: val });\n        monthlyBudget = val;\n        updateBudgetUI(); closeBudgetModal();\n        showToast('Target anggaran disimpan!');\n    } catch(err) { showToast(err.message,'error'); }\n};\n\n// ═══════════════════════════════════════════════════════════════\n// EXPORT\n// ═══════════════════════════════════════════════════════════════\nwindow.exportData = function() {\n    if (transactions.length === 0) { showToast('Tidak ada data untuk diekspor','error'); return; }\n    let csv = 'ID,Tipe,Kategori,Tanggal,Jumlah(Rp),Catatan\\n';\n    transactions.forEach(r => { csv += `${r.id},${r.type},${r.category},${r.date},${r.amount},${(r.note||'').replace(/,/g,'')}\\n`; });\n    const link = document.createElement('a');\n    link.href = 'data:text/csv;charset=utf-8,' + encodeURI(csv);\n    link.download = `rions_${currentUsername}_${today}.csv`;\n    link.click();\n    showToast('Data berhasil diekspor');\n};\n\n// ═══════════════════════════════════════════════════════════════\n// UI HELPERS\n// ═══════════════════════════════════════════════════════════════\nwindow.switchView = async function(view) {\n    currentView = view;\n    if (view === 'transactions') {\n        await loadTransactions();\n    }\n    renderApp();\n};\n\nwindow.setFilter = function(f) { currentFilter = f; renderFullTransactions(); };\n\nwindow.debounceSearch = function() {\n    clearTimeout(searchTimeout);\n    searchTimeout = setTimeout(() => { searchQuery = document.getElementById('searchInput').value; renderFullTransactions(); }, 300);\n};\n\nfunction toggleModal(id, show) {\n    const m = document.getElementById(id);\n    if (show) {\n        m.classList.remove('hidden');\n        setTimeout(() => { m.classList.remove('opacity-0'); const c = m.children[1]; if(c) c.classList.remove('scale-95'); }, 10);\n    } else {\n        const c = m.children[1]; if(c) c.classList.add('scale-95');\n        m.classList.add('opacity-0');\n        setTimeout(() => m.classList.add('hidden'), 200);\n    }\n}\n\nwindow.openModal = function() {\n    document.getElementById('editTxId').value = '';\n    document.getElementById('modalTitle').textContent = 'Tambah Transaksi';\n    document.getElementById('transactionForm').reset();\n    document.getElementById('txDate').value = today;\n    document.querySelector('input[name=\"txType\"][value=\"expense\"]').checked = true;\n    updateCategoryOptions();\n    toggleModal('transactionModal', true);\n};\nwindow.closeModal = function() { toggleModal('transactionModal', false); };\n\nwindow.openBudgetModal = function() {\n    document.getElementById('inputBudgetValue').value = String(monthlyBudget).replace(/\\B(?=(\\d{3})+(?!\\d))/g,'.');\n    toggleModal('budgetModal', true);\n};\nwindow.closeBudgetModal = function() { toggleModal('budgetModal', false); };\n\nwindow.openCategoryModal = function() { renderCategoryList(); toggleModal('categoryModal', true); };\nwindow.closeCategoryModal = function() { toggleModal('categoryModal', false); };\n\nfunction updateNavStyles(v) {\n    const active = 'w-full flex items-center gap-3 px-4 py-3.5 rounded-2xl text-indigo-600 bg-white/60 font-semibold shadow-sm transition-all border border-white/80';\n    const inactive = 'w-full flex items-center gap-3 px-4 py-3.5 rounded-2xl text-slate-500 hover:bg-white/40 hover:text-slate-900 font-medium transition-all';\n    const mActive = 'flex flex-col items-center p-2 text-indigo-600 w-20 transition-transform active:scale-95';\n    const mInactive = 'flex flex-col items-center p-2 text-slate-400 w-20 transition-transform active:scale-95';\n    document.getElementById('nav-dashboard-desktop').className = v==='dashboard'?active:inactive;\n    document.getElementById('nav-transactions-desktop').className = v==='transactions'?active:inactive;\n    document.getElementById('nav-dashboard-mobile').className = v==='dashboard'?mActive:mInactive;\n    document.getElementById('nav-transactions-mobile').className = v==='transactions'?mActive:mInactive;\n}\n\nwindow.showToast = function(msg, type='success') {\n    const c = document.getElementById('toastContainer');\n    const t = document.createElement('div');\n    const isErr = type==='error';\n    t.className = `toast-animate liquid-glass flex items-center gap-3 p-4 rounded-2xl shadow-lg border ${isErr?'border-rose-200':'border-emerald-200'}`;\n    t.innerHTML = `<div class=\"w-8 h-8 rounded-full flex items-center justify-center shrink-0 ${isErr?'bg-rose-100 text-rose-600':'bg-emerald-100 text-emerald-600'}\"><i class=\"ph-bold ${isErr?'ph-warning':'ph-check'} text-lg\"></i></div><p class=\"text-sm font-bold text-slate-800\">${msg}</p>`;\n    c.appendChild(t);\n    setTimeout(()=>t.remove(), 3500);\n};\n\n// ═══════════════════════════════════════════════════════════════\n// BOOT\n// ═══════════════════════════════════════════════════════════════\nwindow.onload = initApp;\n</script>\n</body>\n</html>\n";

const DEFAULT_CATS = [
  { name:'Makanan', type:'expense', icon:'ph-hamburger', color:'text-amber-500', bg:'bg-amber-100/80', hex:'#f59e0b', is_custom:0 },
  { name:'Transportasi', type:'expense', icon:'ph-car', color:'text-blue-500', bg:'bg-blue-100/80', hex:'#3b82f6', is_custom:0 },
  { name:'Belanja', type:'expense', icon:'ph-shopping-bag', color:'text-pink-500', bg:'bg-pink-100/80', hex:'#ec4899', is_custom:0 },
  { name:'Tagihan', type:'expense', icon:'ph-receipt', color:'text-rose-500', bg:'bg-rose-100/80', hex:'#ef4444', is_custom:0 },
  { name:'Hiburan', type:'expense', icon:'ph-film-strip', color:'text-purple-500', bg:'bg-purple-100/80', hex:'#a855f7', is_custom:0 },
  { name:'Lainnya', type:'expense', icon:'ph-dots-three', color:'text-slate-500', bg:'bg-slate-200/80', hex:'#64748b', is_custom:0 },
  { name:'Gaji', type:'income', icon:'ph-money', color:'text-emerald-600', bg:'bg-emerald-100/80', hex:'#059669', is_custom:0 },
  { name:'Lainnya', type:'income', icon:'ph-dots-three', color:'text-slate-500', bg:'bg-slate-200/80', hex:'#64748b', is_custom:0 }
];

// ---------- Supabase REST ----------
async function sb(method, table, query = '', body) {
  let res;
  try {
    res = await fetch(`${SB_URL}/rest/v1/${table}${query}`, {
      method,
      headers: { apikey: SB_KEY, Authorization: `Bearer ${SB_KEY}`, 'Content-Type': 'application/json', Prefer: 'return=representation' },
      body: body ? JSON.stringify(body) : undefined
    });
  } catch (e) {
    const cause = e && e.cause ? (e.cause.code || e.cause.message) : e.message;
    console.error('SUPABASE FETCH ERROR:', cause, '| host:', SB_URL);
    throw new Error('Tidak bisa konek ke Supabase (' + cause + ') host=' + SB_URL);
  }
  const text = await res.text();
  let data = null;
  try { data = text ? JSON.parse(text) : null; } catch { data = { message: text.slice(0, 200) }; }
  if (!res.ok) { console.error('SUPABASE ERROR', res.status, text.slice(0, 300)); throw new Error((data && (data.message || data.error)) || 'Database error ' + res.status); }
  return data;
}

// ---------- Auth helpers ----------
const hashPw = (pw) => { const s = crypto.randomBytes(16).toString('hex'); return s + ':' + crypto.scryptSync(pw, s, 64).toString('hex'); };
const checkPw = (pw, stored) => {
  const [s, h] = stored.split(':');
  const a = Buffer.from(h, 'hex'), b = crypto.scryptSync(pw, s, 64);
  return a.length === b.length && crypto.timingSafeEqual(a, b);
};
const sign = (p) => {
  const b = Buffer.from(JSON.stringify({ ...p, exp: Date.now() + 30 * 864e5 })).toString('base64url');
  return b + '.' + crypto.createHmac('sha256', SECRET).update(b).digest('base64url');
};
const verify = (token) => {
  try {
    const [b, s] = token.split('.');
    const ok = crypto.createHmac('sha256', SECRET).update(b).digest('base64url');
    if (s !== ok) return null;
    const p = JSON.parse(Buffer.from(b, 'base64url').toString());
    return p.exp > Date.now() ? p : null;
  } catch { return null; }
};

const fail = (code, msg) => { const e = new Error(msg); e.code = code; return e; };

module.exports = async (req, res) => {
  const route = (req.query && req.query.r) || '';
  if (!route) { res.setHeader('Content-Type', 'text/html; charset=utf-8'); return res.status(200).send(HTML); }

  if (route === '/debug' || route === 'debug') {
    let host = SB_URL, test;
    try { const r = await fetch(SB_URL + '/rest/v1/users?select=id&limit=1', { headers: { apikey: SB_KEY, Authorization: 'Bearer ' + SB_KEY } }); test = 'HTTP ' + r.status + ' ' + (await r.text()).slice(0, 150); }
    catch (e) { test = 'GAGAL: ' + (e.cause ? (e.cause.code || e.cause.message) : e.message); }
    return res.status(200).json({ url_dipakai: host, key_panjang: SB_KEY.length, key_awal: SB_KEY.slice(0, 6), jwt_secret_ada: !!process.env.JWT_SECRET, tes_koneksi: test });
  }

  try {
    if (!SB_URL || !SB_KEY) throw fail(500, 'Env SUPABASE_URL / SUPABASE_SERVICE_KEY belum diset');
    const body = req.body || {};
    const seg = route.split('/').filter(Boolean);
    const m = req.method;
    const send = (data, code = 200) => res.status(code).json(data);

    // ----- public auth routes -----
    if (seg[0] === 'auth' && seg[1] === 'register' && m === 'POST') {
      const username = String(body.username || '').trim().toLowerCase();
      if (username.length < 3 || String(body.password || '').length < 6) throw fail(400, 'Username min 3 karakter, password min 6 karakter');
      const ex = await sb('GET', 'users', `?username=eq.${encodeURIComponent(username)}&select=id`);
      if (ex.length) throw fail(409, 'Username sudah digunakan');
      const [u] = await sb('POST', 'users', '', { username, password_hash: hashPw(body.password), categories: DEFAULT_CATS });
      return send({ token: sign({ id: u.id, username }), username });
    }
    if (seg[0] === 'auth' && seg[1] === 'login' && m === 'POST') {
      const username = String(body.username || '').trim().toLowerCase();
      const [u] = await sb('GET', 'users', `?username=eq.${encodeURIComponent(username)}`);
      if (!u || !checkPw(String(body.password || ''), u.password_hash)) throw fail(401, 'Username atau password salah');
      return send({ token: sign({ id: u.id, username }), username, budget: Number(u.monthly_budget) });
    }

    // ----- protected routes -----
    const auth = (req.headers.authorization || '').replace('Bearer ', '');
    const user = verify(auth);
    if (!user) throw fail(401, 'Sesi berakhir, silakan login ulang');
    const uid = user.id;
    const getUser = async () => (await sb('GET', 'users', `?id=eq.${uid}`))[0];

    if (seg[0] === 'auth' && seg[1] === 'me') { const u = await getUser(); return send({ username: u.username, monthly_budget: Number(u.monthly_budget) }); }

    if (seg[0] === 'budget' && m === 'PUT') {
      const v = Number(body.monthly_budget);
      if (!v || v < 0) throw fail(400, 'Anggaran tidak valid');
      await sb('PATCH', 'users', `?id=eq.${uid}`, { monthly_budget: v });
      return send({ monthly_budget: v });
    }

    if (seg[0] === 'categories') {
      const u = await getUser(); const cats = u.categories || [];
      if (m === 'GET') return send(cats.map((c, i) => ({ ...c, id: i })));
      if (m === 'POST') {
        const name = String(body.name || '').trim();
        if (!name || !['expense', 'income'].includes(body.type)) throw fail(400, 'Data kategori tidak valid');
        if (cats.some(c => c.type === body.type && c.name.toLowerCase() === name.toLowerCase())) throw fail(409, 'Kategori sudah ada');
        cats.push({ name, type: body.type, icon: 'ph-tag', color: 'text-indigo-500', bg: 'bg-indigo-100/80', hex: '#6366f1', is_custom: 1 });
        await sb('PATCH', 'users', `?id=eq.${uid}`, { categories: cats });
        return send({ success: true }, 201);
      }
      if (m === 'DELETE') {
        const i = Number(seg[1]);
        if (!cats[i]) throw fail(404, 'Kategori tidak ditemukan');
        if (!cats[i].is_custom) throw fail(403, 'Kategori default tidak bisa dihapus');
        cats.splice(i, 1);
        await sb('PATCH', 'users', `?id=eq.${uid}`, { categories: cats });
        return send({ success: true });
      }
    }

    if (seg[0] === 'transactions') {
      if (seg[1] === 'summary' && m === 'GET') {
        const txs = await sb('GET', 'transactions', `?user_id=eq.${uid}&select=type,amount,category,date`);
        let income = 0, expense = 0; const cat = {}, tr = {};
        for (const t of txs) {
          const a = Number(t.amount), mo = String(t.date).slice(0, 7);
          tr[mo] = tr[mo] || { month: mo, income: 0, expense: 0 };
          if (t.type === 'income') { income += a; tr[mo].income += a; } else { expense += a; tr[mo].expense += a; }
          const k = t.type + '|' + t.category; cat[k] = (cat[k] || 0) + a;
        }
        const byCategory = Object.entries(cat).map(([k, total]) => { const [type, category] = k.split('|'); return { type, category, total }; }).sort((a, b) => b.total - a.total);
        const trend = Object.values(tr).sort((a, b) => a.month.localeCompare(b.month)).slice(-6);
        return send({ income, expense, balance: income - expense, byCategory, trend });
      }
      if (m === 'GET') return send((await sb('GET', 'transactions', `?user_id=eq.${uid}&order=date.desc,id.desc`)).map(t => ({ ...t, amount: Number(t.amount) })));

      const clean = () => {
        const amount = Number(body.amount);
        if (!['expense', 'income'].includes(body.type) || !(amount > 0) || !body.category || !body.date) throw fail(400, 'Data transaksi tidak lengkap');
        return { type: body.type, amount, category: String(body.category), date: body.date, note: String(body.note || '') };
      };
      if (m === 'POST') { const [t] = await sb('POST', 'transactions', '', { ...clean(), user_id: uid }); return send(t, 201); }
      if (m === 'PUT' && seg[1]) { const r = await sb('PATCH', 'transactions', `?id=eq.${Number(seg[1])}&user_id=eq.${uid}`, clean()); if (!r.length) throw fail(404, 'Transaksi tidak ditemukan'); return send(r[0]); }
      if (m === 'DELETE' && seg[1]) { await sb('DELETE', 'transactions', `?id=eq.${Number(seg[1])}&user_id=eq.${uid}`); return send({ success: true }); }
    }

    throw fail(404, 'Endpoint tidak ditemukan');
  } catch (e) {
    console.error('API ERROR:', e && e.stack || e);
    res.status(e.code || 500).json({ error: e.message });
  }
};
